/**
 * The CoreEdge status vocabulary — the ONLY place a status becomes words.
 *
 * Generated by hand from `docs/coreedge/design/A5-CoreEdge-Status-Vocabulary.csv`
 * and section 5 of `docs/coreedge/design/CoreEdge Engineering Handoff.dc.html`.
 * Both are committed, so every value below can be checked against its source.
 *
 * WHY ONE MODULE. The audit found 87 distinct status literals across the
 * codebase, spelled in at least four conventions — SCREAMING_SNAKE enums,
 * lowercase strings, Title Case prose and severity words — and mapped to colour
 * in nine different components. A lane's status is the single most consequential
 * thing this console says, and it was being decided nine times. Everything the
 * new console renders resolves through this file, and
 * `tests/unit/coreedge/status-vocabulary.test.ts` fails if any of those 87
 * literals has no mapping, so a new backend status cannot reach a screen as an
 * unstyled raw string.
 *
 * WHAT IS DELIBERATELY ABSENT: a "checking" status. The handoff is explicit —
 * "there is no 'checking' status — that would be a nineteenth vocabulary entry
 * for a transient." A lane keeps its last known status while a re-check runs.
 */

/* ─────────────────────────────────────────────────────────────────────────────
 * Tokens and glyphs
 * ────────────────────────────────────────────────────────────────────────── */

/**
 * The five chip tokens. These are token NAMES, resolved by
 * `src/app/coreedge-tokens.css` — never colours.
 */
export const GATE_TOKENS = ["gate-ok", "gate-info", "gate-wait", "gate-bad", "gate-off"] as const;
export type GateToken = (typeof GATE_TOKENS)[number];

/**
 * THE GLYPH IS A CONTRACT, NOT DECORATION, and it hangs off the token rather
 * than off the status so that it cannot be omitted for one status and not
 * another.
 *
 * PR-1 measured the reason: in dark mode the fifteen pairwise contrasts between
 * the six status grounds all sit between 1.01:1 and 1.10:1
 * (`tests/unit/coreedge/token-contrast.test.ts`). Colour alone does not
 * distinguish them for anyone — not only for colour-blind users. The glyph is
 * what carries the meaning; the colour merely agrees with it.
 */
export const GATE_GLYPHS: Readonly<Record<GateToken, string>> = {
  "gate-ok": "✓",
  "gate-info": "i",
  "gate-wait": "…",
  "gate-bad": "✕",
  "gate-off": "–",
};

/* ─────────────────────────────────────────────────────────────────────────────
 * The six hops
 * ────────────────────────────────────────────────────────────────────────── */

/**
 * A lane is six hops, in this order. From A1 section 5: "Key → Access → Binding
 * → SAP metadata → SAP data read → App".
 */
export const LANE_HOPS = ["key", "access", "binding", "sapMetadata", "sapDataRead", "app"] as const;
export type LaneHop = (typeof LANE_HOPS)[number];

export const HOP_LABELS: Readonly<Record<LaneHop, string>> = {
  key: "Key",
  access: "Access",
  binding: "Binding",
  sapMetadata: "SAP metadata",
  sapDataRead: "SAP data read",
  app: "Your app",
};

/**
 * RECONCILIATION, RECORDED BECAUSE THE TWO SOURCES DISAGREE.
 *
 * A1 and the handoff's WhyTrace entry both name the same six hops. The handoff's
 * section 5 table, however, fills its "Broken hop" column with two labels that
 * are not among them — `Traffic` and `SAP system` — and uses `Binding` for a
 * third status that is plainly the same hop as the `SAP system` ones. So the
 * handoff carries two vocabularies and this file has to pick one.
 *
 * It picks the six, because they are what the trace renders and what A1 states
 * normatively. The two odd labels are resolved as:
 *
 *   · `SAP system`  → `binding`. The binding hop IS "is there exactly one usable
 *     SAP system for this environment". All four statuses the handoff files
 *     under `SAP system` (No SAP system, System off, Secret unreadable) plus the
 *     one it already files under `Binding` (Binding refused) are the same
 *     question failing for four different reasons, and share one owner:
 *     platform admin.
 *   · `Traffic`     → `null`. It appears once, on `No data`, whose own row says
 *     "SAP answered and had nothing to return. A success." Nothing is broken, so
 *     no hop is named. Recording `Traffic` as a broken hop would put a failure
 *     marker on a lane that worked.
 *
 * Each status keeps the handoff's verbatim column value in `handoffHopLabel`, so
 * the mapping is auditable and nothing from the source is silently discarded.
 */
export type HandoffHopLabel =
  | "—"
  | "Traffic"
  | "Access"
  | "Key"
  | "Binding"
  | "SAP system"
  | "SAP metadata"
  | "SAP data read";

/* ─────────────────────────────────────────────────────────────────────────────
 * Owners
 * ────────────────────────────────────────────────────────────────────────── */

/**
 * Who fixes it. The handoff's rule: "A status earns its own wording only when it
 * changes who fixes it — that is why 401 and 403 are separate". The owner is
 * therefore load-bearing, not annotation: it is the reason two statuses exist
 * where one colour would do.
 */
export const STATUS_OWNERS = [
  "appOwner",
  "reviewer",
  "platformAdmin",
  "clientSapAdmin",
  "clientBasisTeam",
  "operator",
] as const;
export type StatusOwner = (typeof STATUS_OWNERS)[number];

export const OWNER_LABELS: Readonly<Record<StatusOwner, string>> = {
  appOwner: "App owner",
  reviewer: "Reviewer",
  platformAdmin: "Platform admin",
  clientSapAdmin: "Client SAP admin",
  clientBasisTeam: "Client Basis team",
  operator: "Operator",
};

/* ─────────────────────────────────────────────────────────────────────────────
 * The eighteen lane statuses
 * ────────────────────────────────────────────────────────────────────────── */

export const LANE_STATUSES = [
  "live",
  "noData",
  "inReview",
  "noAccess",
  "accessEnded",
  "noKey",
  "keyNotValid",
  "rateLimited",
  "bindingRefused",
  "noSapSystem",
  "systemOff",
  "secretUnreadable",
  "signInRefused",
  "sapRefused",
  "sapUnavailable",
  "circuitOpen",
  "unknown",
  "notStarted",
] as const;
export type LaneStatus = (typeof LANE_STATUSES)[number];

export interface LaneStatusDefinition {
  /** The words on the chip. Never construct this — the label IS the status. */
  readonly label: string;
  readonly token: GateToken;
  /** The hop that failed, or null when nothing failed. See the reconciliation above. */
  readonly brokenHop: LaneHop | null;
  /** The handoff's own "Broken hop" column, verbatim, so the mapping is checkable. */
  readonly handoffHopLabel: HandoffHopLabel;
  /** Who fixes it. Null only where the handoff's Owner column is "—". */
  readonly owner: StatusOwner | null;
  /** The handoff's "Means" column, verbatim. Shown in WhyTrace and the ops legend. */
  readonly means: string;
}

