/**
 * Resolve a literal to a lane status.
 *
 * Returns `undefined` for a literal this file has never heard of — deliberately
 * distinct from `null`, which means "known, and deliberately not a lane chip".
 * A caller that cannot tell those apart would render an unmapped status as if it
 * had been considered.
 */
export function laneStatusForLiteral(
  literal: string,
  domain?: LiteralDomain,
): LaneStatus | null | undefined {
  const match = STATUS_LITERAL_MAP.find(
    (m) => m.literal === literal && (domain === undefined || m.domain === domain),
  );
  return match === undefined ? undefined : match.lane;
}

/* ─────────────────────────────────────────────────────────────────────────────
 * App-level status (DECISION D3)
 * ────────────────────────────────────────────────────────────────────────── */

export const APP_STATUSES = ["draft", "active", "restricted", "retired"] as const;
export type AppStatus = (typeof APP_STATUSES)[number];

/**
 * App chips can also carry `status-expired`, which A5 assigns to RETIRED. It is
 * a real A2 token (`--status-expired-bg/-fg`, declared in both themes and
 * shipped in `src/app/coreedge-tokens.css`) but deliberately NOT one of the five
 * gate tokens: gate tokens describe a hop's condition, and a retired app has no
 * hops left to describe. The type is widened rather than the value cast, so the
 * distinction survives.
 */
export type AppChipToken = GateToken | "status-expired";

/**
 * INVENTED, AND FLAGGED AS SUCH. The design specifies glyphs for the five gate
 * tokens only (✓ i … ✕ –); `status-expired` has none anywhere in the bundle.
 * Since "every status carries a glyph" is a contract rather than a preference,
 * an app chip could not ship without one.
 *
 * `✕` is the choice: a retired app's calls are refused outright by
 * checkSolutionRuntime, so the chip makes the same hard-stop claim gate-bad
 * makes. The alternative considered was `–` (gate-off's "nothing here"), which
 * would understate it — a retired app is not dormant, it actively refuses.
 */
export const APP_CHIP_GLYPHS: Readonly<Record<AppChipToken, string>> = {
  ...GATE_GLYPHS,
  "status-expired": "✕",
};

export interface AppStatusDefinition {
  readonly label: string;
  readonly token: AppChipToken;
  readonly owner: StatusOwner | null;
  readonly means: string;
}

/**
 * App statuses render ONE chip at app level. They are not lane statuses and
 * never appear on a lane cell.
 *
 * DECISION D3, implemented as stated: Restricted means no new access is
 * requested or approved; existing lanes keep serving and keep their own
 * statuses. Its chip reads "Restricted · no new access", with the gate-wait
 * token and the platform admin as owner.
 *
 * This diverges from A5, which gives RESTRICTED the plain label "Needs an owner"
 * and the note "Lost an owner; still served". The divergence is deliberate and
 * settled: "Needs an owner" describes the cause, "no new access" describes the
 * consequence, and the consequence is what the person reading the chip has to
 * act on. A5's row is left intact in the bundle so the two can be compared.
 */
export const APP_STATUS_VOCABULARY: Readonly<Record<AppStatus, AppStatusDefinition>> = {
  draft: {
    label: "Draft",
    token: "gate-off",
    owner: "appOwner",
    means: "Being set up. Nothing is served yet.",
  },
  active: {
    label: "Active",
    token: "gate-ok",
    owner: null,
    means: "Owners assigned. Lanes serve according to their own statuses.",
  },
  restricted: {
    label: "Restricted · no new access",
    token: "gate-wait",
    owner: "platformAdmin",
    means: "No new access can be requested or approved. Existing lanes keep serving.",
  },
  retired: {
    label: "Retired",
    token: "status-expired",
    owner: "appOwner",
    means: "Northbound refuses every call. Existing keys stop working.",
  },
};

/** The glyph for an app status. Like lanes, derived from the token. */
export function appGlyphFor(status: AppStatus): string {
  return APP_CHIP_GLYPHS[APP_STATUS_VOCABULARY[status].token];
}

/** Glyph and label together: "✕ Retired". */
export function appChipTextFor(status: AppStatus): string {
  return `${appGlyphFor(status)} ${APP_STATUS_VOCABULARY[status].label}`;
}
